import { apiError, err, ok, type ApiError, type Result, type SignInKeySource } from "@officebox/shared";
import type { Env } from "../env";
import type { GeneratedKeyName } from "../system-object";
import type { Logger } from "./log";

/**
 * Keys generated by the Worker (Platform §16, TDD §8.1; product-owner decision 16 Nov 2026, M1b-1).
 *
 * `BETTER_AUTH_SECRET` and `TOKEN_HASH_KEY` come from their Worker secret whenever one is set. While a
 * key's Worker secret is **absent (unset or empty)**, the Worker uses a key generated once by the
 * SystemObject (`generatedKey` RPC) and kept only in its storage. The two keys are decided
 * independently. A secret that is set but invalid is the caller's error (`/not-configured`), never a
 * reason to fall back.
 *
 * - Each isolate caches a generated key for its lifetime (keyed by the SYSTEM binding, so tests with
 *   other bindings don't share it). Only a key read successfully is cached.
 * - If the object can't be reached, the result is `unreachable` and the request answers `unavailable`:
 *   an isolate never invents a key of its own.
 * - The value is never logged (only the key's **name** and the failure), never written to D1 and never
 *   returned by any route.
 */

/** Whether a Worker secret counts as set: an empty value counts as unset (Platform §16). */
export function secretIsSet(value: string | undefined): value is string {
  return value !== undefined && value !== "";
}

/** Each key's source, from the Worker secrets alone (Admin → Settings shows this, never a value). */
export function signInKeySources(env: Pick<Env, "BETTER_AUTH_SECRET" | "BETTER_AUTH_SECRETS" | "TOKEN_HASH_KEY">): {
  betterAuthSecret: SignInKeySource;
  tokenHashKey: SignInKeySource;
} {
  return {
    betterAuthSecret:
      secretIsSet(env.BETTER_AUTH_SECRETS) || secretIsSet(env.BETTER_AUTH_SECRET) ? "worker_secret" : "generated",
    tokenHashKey: secretIsSet(env.TOKEN_HASH_KEY) ? "worker_secret" : "generated",
  };
}

let cache = new WeakMap<object, Map<GeneratedKeyName, string>>();

/** Forgets this isolate's generated keys (tests that evict the SystemObject). */
export function clearGeneratedKeyCache(): void {
  cache = new WeakMap();
}

export const KEY_UNREACHABLE: ApiError = apiError(
  "unavailable",
  "Sign-in keys can't be read right now. Try again in a moment.",
  { reason: "keys_unreachable" },
);

/**
 * The generated key `name`, from this isolate's cache or the SystemObject. `KEY_UNREACHABLE` when the
 * object can't be reached or refuses (its schema migration failed, say).
 */
export async function generatedKey(
  env: Pick<Env, "SYSTEM">,
  name: GeneratedKeyName,
  log: Logger,
): Promise<Result<string, ApiError>> {
  const binding = env.SYSTEM as object | undefined;
  if (!binding) {
    log.error("generated key unavailable: the SYSTEM Durable Object binding is missing", { key: name });
    return err(KEY_UNREACHABLE);
  }
  const keys = cache.get(binding) ?? new Map<GeneratedKeyName, string>();
  cache.set(binding, keys);
  const hit = keys.get(name);
  if (hit !== undefined) return ok(hit);
  try {
    const result = await env.SYSTEM.getByName("system").generatedKey(name);
    if (!result.ok) {
      log.error("generated key unavailable: the SystemObject refused", { key: name, code: result.error.code });
      return err(KEY_UNREACHABLE);
    }
    keys.set(name, result.value.value);
    return ok(result.value.value);
  } catch (error) {
    log.error("generated key unavailable: the SystemObject can't be reached", { key: name, error });
    return err(KEY_UNREACHABLE);
  }
}

/**
 * `TOKEN_HASH_KEY` for code outside the identity routes (audit pseudonyms, engine facts): the Worker
 * secret when set (whatever its length, as before), otherwise the generated key; null when neither can
 * be had, so callers mask instead of failing.
 */
export async function tokenHashKeyOrNull(env: Pick<Env, "TOKEN_HASH_KEY"> & Partial<Pick<Env, "SYSTEM">>, log: Logger) {
  if (secretIsSet(env.TOKEN_HASH_KEY)) return env.TOKEN_HASH_KEY;
  if (!env.SYSTEM) return null;
  const key = await generatedKey({ SYSTEM: env.SYSTEM }, "token_hash_key", log);
  return key.ok ? key.value : null;
}

let noted = new WeakMap<object, Set<string>>();

/** Forgets which key sources this isolate has already recorded (tests). */
export function clearKeySourceNotes(): void {
  noted = new WeakMap();
}

/**
 * Records, once per isolate per key and source, where a key resolved from, and logs a warning when that
 * differs from what the SystemObject recorded before: a Worker secret set (or deleted) on a running
 * workspace signs everyone out or invalidates outstanding links (Platform §16). Never logs a value.
 * Best effort: a failure here never fails the request.
 */
export async function noteKeySource(
  env: Partial<Pick<Env, "SYSTEM">>,
  name: GeneratedKeyName,
  source: SignInKeySource,
  log: Logger,
): Promise<void> {
  const binding = env.SYSTEM as object | undefined;
  if (!env.SYSTEM || !binding) return;
  const seen = noted.get(binding) ?? new Set<string>();
  noted.set(binding, seen);
  const tag = `${name}:${source}`;
  if (seen.has(tag)) return;
  seen.add(tag);
  try {
    const result = await env.SYSTEM.getByName("system").recordKeySource(name, source);
    if (result.ok && result.value.previous) {
      log.warn("sign-in key source changed: sessions or outstanding links made with the old key no longer work", {
        key: name,
        from: result.value.previous.source,
        to: source,
        previousSince: new Date(result.value.previous.since).toISOString(),
      });
    }
  } catch {
    seen.delete(tag); // try again on a later request
  }
}
